{const file="FS25_FarmDashboard_App/tests/mergeTransientPool.integration.test.js";let s=fs.readFileSync(file,'utf8').replace(/\r\n/g,'\n');s="'use strict';\n// Required hermetic fixtures: a missing or unsuitable live cache cannot turn these into passes.\nconst { mergeData } = require('../dataMerger');\nconst { pruneMergedDataToPlayerFarms } = require('../farmScope.cjs');\nfunction fixture() {\n    return {\n        serverInfo:{farmId:3,activeFarmId:3}, farmInfo:[{id:3,farmId:3,name:'Test farm'}],\n        animals:[{id:7,ownerFarmId:3,animalCount:5}],\n        vehicles:[\n            {id:'demo',uniqueId:'demo',name:'Shop demo',ownerFarmId:100,needsSaving:false,propertyState:'SHOP_CONFIG',configFileName:'data/vehicles/demo.xml'},\n            {id:'owned',uniqueId:'owned',name:'Owned tractor',ownerFarmId:100,needsSaving:true,propertyState:'OWNED',configFileName:'data/vehicles/tractor.xml'},\n        ],\n    };\n}\ntest('dealership demo does not leak into the player fleet',()=>{\n    const lua=fixture();\n    expect(lua.vehicles.filter(v=>v.needsSaving===false)).toHaveLength(1);\n    const result=pruneMergedDataToPlayerFarms(mergeData(lua,null));\n    expect(result.vehicles.some(v=>String(v.uniqueId||v.id)==='demo')).toBe(false);\n});\ntest('authoritative XML owner resolves a player record without a live-cache precondition',()=>{\n    const lua=fixture();\n    const xml={vehicles:[{...lua.vehicles[1],ownerFarmId:3,farmId:3}],farms:[{id:3,farmId:3,name:'Test farm'}]};\n    const result=mergeData(lua,xml);\n    const owned=result.vehicles.filter(v=>String(v.uniqueId||v.id)==='owned');\n    expect(owned).toHaveLength(1);\n    expect(Number(owned[0].ownerFarmId||owned[0].farmId)).toBe(3);\n});\n";
writes.push({file,content:s});}
for(const entry of [{"path":"FS25_FarmDashboard_App/tests/helpers/production-source.cjs","content":"'use strict';\nconst fs = require('fs');\nconst path = require('path');\nconst vm = require('vm');\nconst { createRequire } = require('module');\nconst ts = require('../../../NEW APP/node_modules/typescript');\nconst root = path.resolve(__dirname, '../../..');\n\nfunction productionFunctions(relative, names, globals = {}) {\n    const file = path.join(root, relative);\n    const source = fs.readFileSync(file, 'utf8');\n    const ast = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true);\n    const code = names.map(name => {\n        const declaration = ast.statements.find(node => ts.isFunctionDeclaration(node) && node.name?.text === name);\n        if (!declaration) throw new Error('Missing production function: ' + name);\n        return declaration.getText(ast).replace(/^export\\s+/, '');\n    }).join('\\n') + '\\nmodule.exports = {' + names.join(',') + '};';\n    const output = ts.transpileModule(code, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;\n    const module = { exports: {} };\n    vm.runInNewContext(output, {\n        module, exports: module.exports, require: createRequire(file), __dirname: path.dirname(file),\n        console, URL, Buffer, Date, setTimeout, clearTimeout, path, ...globals,\n    });\n    return module.exports;\n}\n\nfunction productionTs(relative, mocks = {}) {\n    const file = path.join(root, relative);\n    const source = fs.readFileSync(file, 'utf8');\n    const output = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;\n    const module = { exports: {} };\n    const localRequire = id => {\n        if (Object.prototype.hasOwnProperty.call(mocks, id)) return mocks[id];\n        if (id === 'preact/hooks') return require('../../../NEW APP/node_modules/preact/hooks');\n        return createRequire(file)(id);\n    };\n    new Function('require', 'module', 'exports', 'document', 'window', output)(\n        localRequire, module, module.exports, global.document, global.window,\n    );\n    return module.exports;\n}\n\nmodule.exports = { productionFunctions, productionTs };\n"},{"path":"FS25_FarmDashboard_App/tests/releaseSafety.regression.test.js","content":"'use strict';\nconst fs = require('fs');\nconst os = require('os');\nconst path = require('path');\nconst { pathToFileURL } = require('url');\nconst { EventEmitter } = require('events');\nconst { productionFunctions } = require('./helpers/production-source.cjs');\nconst policy = require('../editionPolicy.cjs');\nconst config = require('../setupConfigMerge.cjs');\nconst fileCommit = require('../fileCommit.cjs');\n\ndescribe('release trust regressions against production', () => {\n    const guards = () => productionFunctions('FS25_FarmDashboard_App/main.js',\n        ['getRequestOrigin', 'isAllowedSameOrigin', 'enforceWriteOriginAndToken', 'webSocketOriginAllowed'], {\n            PORT: 8768, isLocalServerHost: h => ['localhost','127.0.0.1'].includes(h),\n            corsOriginAllowedPure: () => false, MARKETING_SITE_HOSTS: [], getCachedLocalInterfaceIps: () => [],\n            isLocalhostSocket: () => true, isRequestFromThisMachine: () => false,\n            isLoopbackIp: () => true, requestRemoteAddress: () => '127.0.0.1',\n        });\n    test.each(['null', '::::', '', 'file:///C:/outside.html', 'https://evil.invalid'])('reject browser Origin %p for writes and WS', origin => {\n        const g = guards(), req = { headers: { origin, host: '127.0.0.1:8768' } };\n        expect(g.enforceWriteOriginAndToken(req, {})).toBeTruthy();\n        expect(g.webSocketOriginAllowed(req)).toBe(false);\n    });\n    test('explicit absent-origin native compatibility and same-origin browser still work', () => {\n        const g = guards();\n        expect(g.enforceWriteOriginAndToken({ headers: {} }, {})).toBeNull();\n        expect(g.webSocketOriginAllowed({ headers: { origin: 'http://127.0.0.1:8768' } })).toBe(true);\n    });\n    test('only exact application documents are trusted', () => {\n        const appDirectory = path.resolve(__dirname, '..');\n        expect(policy.isTrustedDashboardIpcUrl(pathToFileURL(path.join(appDirectory, 'setup.html')).href, { port:8768, appDirectory })).toBe(true);\n        for (const url of ['file:///C:/Temp/index.html','file:///C:/Temp/setup.html','http://localhost/','http://127.0.0.1:8768/untrusted.html','https://127.0.0.1:8768/']) {\n            expect(policy.isTrustedDashboardIpcUrl(url,{port:8768,appDirectory})).toBe(false);\n        }\n    });\n    test('privileged sender must be the expected main frame', () => {\n        const frame = { url:'http://127.0.0.1:8768/' };\n        const wc = { mainFrame:frame, isDestroyed:()=>false, getURL:()=>frame.url };\n        const g = productionFunctions('FS25_FarmDashboard_App/main.js',['isTrustedDashboardIpcSender'], {\n            mainWindow:{isDestroyed:()=>false,webContents:wc}, editionPolicy:policy, PORT:8768,\n        });\n        expect(g.isTrustedDashboardIpcSender({sender:wc,senderFrame:frame})).toBe(true);\n        expect(g.isTrustedDashboardIpcSender({sender:wc,senderFrame:{url:frame.url}})).toBe(false);\n        expect(g.isTrustedDashboardIpcSender({sender:{...wc},senderFrame:frame})).toBe(false);\n    });\n    test('secure import policy survives while secrets do not', () => {\n        const row = policy.sanitizeClassicConfigForRf({servers:[{id:'test',mode:'ftp',ftpSecure:'explicit',ftpFtps:true,ftpAllowInsecureTls:false,httpFeedSecure:true,ftpPass:'synthetic',httpFeedCode:'synthetic'}]}).servers[0];\n        expect(row).toMatchObject({ftpSecure:'explicit',ftpFtps:true,ftpAllowInsecureTls:false,httpFeedSecure:true});\n        expect(row.ftpPass).toBeUndefined(); expect(row.httpFeedCode).toBeUndefined();\n    });\n    test.each(['ftpSecure','ftpFtps','ftpAllowInsecureTls','httpFeedSecure'])('policy-only change invalidates captured clients: %s', field => {\n        const previous={servers:[{id:'test',mode:'ftp'}]};\n        expect(config.configNeedsServerReboot(previous,{servers:[{...previous.servers[0],[field]:true}]})).toBe(true);\n    });\n    test.each(['animals_x\\\\..\\\\..\\\\outside.json','animals_../outside.json','animals_x:payload.json','animals_x%2foutside.json'])('reject hostile FTP name %p before download', async name => {\n        const downloads=[];\n        const f=productionFunctions('FS25_FarmDashboard_App/main.js',['syncFtpDetailsCache'], {\n            fs:{promises:{mkdir:async()=>{}}},serverStates:{test:{lastSaveSlot:'savegame1'}},FTP_FILE_TYPE_DIRECTORY:2,\n            pathExists:async()=>false,safeDownload:async(...args)=>{downloads.push(args);return true;},\n            safeFsIdentity:require('../safeFsIdentity.cjs'),\n        });\n        await f.syncFtpDetailsCache({list:async()=>[{name,type:1,size:5}]},{id:'test'},'profile/savegame1',path.join(os.tmpdir(),'synthetic-root'));\n        expect(downloads).toHaveLength(0);\n    });\n});\n\ndescribe('last-good filesystem commit', () => {\n    let root;\n    beforeEach(()=>{root=fs.mkdtempSync(path.join(os.tmpdir(),'farmdash-commit-test-'));});\n    afterEach(()=>{jest.restoreAllMocks();fs.rmSync(root,{recursive:true,force:true});});\n    const client = body => ({downloadTo:async file=>fs.promises.writeFile(file,JSON.stringify(body))});\n    test('failed async rename preserves final bytes', async()=>{\n        const final=path.join(root,'data.json');fs.writeFileSync(final,'{\"old\":true}');\n        jest.spyOn(fs.promises,'rename').mockRejectedValue(Object.assign(new Error('locked'),{code:'EACCES'}));\n        expect(await fileCommit.downloadAndCommit(client({new:true}),'remote',final+'.tmp',final)).toBe(false);\n        expect(fs.readFileSync(final,'utf8')).toBe('{\"old\":true}');\n        expect(fs.readdirSync(root).some(n=>n.includes('.tmp.'))).toBe(true);\n    });\n    test('valid replacement succeeds on the real temporary filesystem',async()=>{\n        const final=path.join(root,'data.json');fs.writeFileSync(final,'{\"old\":true}');\n        expect(await fileCommit.downloadAndCommit(client({new:true}),'remote',final+'.tmp',final)).toBe(true);\n        expect(JSON.parse(fs.readFileSync(final,'utf8'))).toEqual({new:true});\n    });\n    test('truncated JSON never replaces final',async()=>{\n        const final=path.join(root,'data.json');fs.writeFileSync(final,'{\"old\":true}');\n        expect(await fileCommit.downloadAndCommit({downloadTo:async file=>fs.promises.writeFile(file,'{\"bad\":')},'remote',final+'.tmp',final)).toBe(false);\n        expect(fs.readFileSync(final,'utf8')).toBe('{\"old\":true}');\n    });\n    test('cancellation immediately before commit prevents obsolete bytes',async()=>{\n        const final=path.join(root,'data.json');fs.writeFileSync(final,'{\"old\":true}');let active=true;\n        const transfer={downloadTo:async file=>{await fs.promises.writeFile(file,'{\"new\":true}');active=false;}};\n        expect(await fileCommit.downloadAndCommit(transfer,'remote',final+'.tmp',final,{canCommit:()=>active})).toBe(false);\n        expect(fs.readFileSync(final,'utf8')).toBe('{\"old\":true}');\n    });\n    test('sync writer does not delete the last-good file on rename failure',()=>{\n        const final=path.join(root,'requests.json');fs.writeFileSync(final,'{\"old\":true}');\n        jest.spyOn(fs,'renameSync').mockImplementation(()=>{throw Object.assign(new Error('locked'),{code:'EPERM'});});\n        expect(fileCommit.writeJsonAtomicSync(final,{new:true})).toBe(false);\n        expect(fs.readFileSync(final,'utf8')).toBe('{\"old\":true}');\n    });\n});\n\ndescribe('provenance and freshness regressions',()=>{\n    const detail=productionFunctions('FS25_FarmDashboard_App/detailAnimalsHydrate.js',\n        ['countCapturedHeads','hasUniqueIndividuals','husbandryAggregateHeadCount','shouldSkipIncompleteDetail','applyDetailBlockToHusbandry','makeCacheEntry'],\n        {UNIQUE_CAPTURE_RATIO:.8});\n    test('authoritative zero excludes retained detail',()=>{\n        const result=detail.applyDetailBlockToHusbandry({id:7,animalCount:0,numOfAnimalsReported:0,clusters:[]},{ownerFarmId:1,animals:[{uniqueId:'old'}]});\n        expect(result.husbandry.animals).toHaveLength(0);expect(result.hydrated).toBe(false);\n    });\n    test('missing count is not treated as zero',()=>{\n        const result=detail.applyDetailBlockToHusbandry({id:7},{ownerFarmId:1,animals:[{uniqueId:'current'}]});\n        expect(result.husbandry.animals).toHaveLength(1);\n    });\n    test('detail generation survives caching',()=>{\n        expect(detail.makeCacheEntry({mtimeMs:1,size:2},{placeableId:7,generatedAt:123},[]).generatedAt).toBe(123);\n    });\n    test('individual XML identity changes below maximum mtime',async()=>{\n        let changed=1000;\n        const fp=productionFunctions('FS25_FarmDashboard_App/xmlCollector.js',['getSavegameXmlFingerprint'], {\n            getSavegamePathAsync:async()=>path.join(os.tmpdir(),'synthetic-xml'),SAVEGAME_XML_FILES:['a.xml','b.xml'],OPTIONAL_SAVEGAME_XML_FILES:[],\n            fs:{stat:async file=>({mtimeMs:file.endsWith('a.xml')?9999:changed,size:100})},\n        });\n        const before=await fp.getSavegameXmlFingerprint({},'savegame1');changed=2000;\n        expect(await fp.getSavegameXmlFingerprint({},'savegame1')).not.toBe(before);\n    });\n});\n\ndescribe('HTTP total deadline and stream settlement',()=>{\n    afterEach(()=>jest.useRealTimers());\n    function setup() {\n        const response=new EventEmitter();Object.assign(response,{statusCode:200,headers:{},complete:false,destroy:jest.fn()});\n        const request=new EventEmitter();request.destroy=jest.fn();\n        const transport={get:(_url,_options,callback)=>{queueMicrotask(()=>callback(response));return request;}};\n        const mod=productionFunctions('FS25_FarmDashboard_App/httpFeedXml.js',['httpGetBuffer'],{\n            http:transport,https:transport,HTTP_FEED_MAX_HOPS:5,HTTP_FEED_MAX_BYTES:1024,HTTP_FEED_DEADLINE_MS:45000,\n        });\n        return {response,request,mod};\n    }\n    test('continuous traffic cannot extend the absolute 45 second timer',async()=>{\n        jest.useFakeTimers({doNotFake:['queueMicrotask']});const {response,mod}=setup();\n        const result=mod.httpGetBuffer('http://synthetic.invalid/feed').catch(error=>error);\n        await Promise.resolve();\n        for(let i=0;i<4;i++){jest.advanceTimersByTime(10000);response.emit('data',Buffer.from('x'));}\n        jest.advanceTimersByTime(5000);\n        expect((await result).message).toMatch(/total deadline/);expect(jest.getTimerCount()).toBe(0);\n    });\n    test.each(['aborted','close'])('body %s settles instead of hanging',async event=>{\n        const {response,mod}=setup();const result=mod.httpGetBuffer('http://synthetic.invalid/feed').catch(error=>error);\n        await Promise.resolve();response.emit(event);expect((await result).message).toMatch(/aborted|closed/);\n    });\n    test('cross-origin redirects are rejected',async()=>{\n        const {response,mod}=setup();response.statusCode=302;response.headers.location='https://outside.invalid/?code=synthetic';\n        const result=await mod.httpGetBuffer('http://synthetic.invalid/feed').catch(error=>error);\n        expect(result.message).toMatch(/cross-origin/);\n    });\n});\n"},{"path":"FS25_FarmDashboard_App/tests/releaseUi.regression.test.js","content":"/** @jest-environment jsdom */\n'use strict';\nconst { h, render } = require('../../NEW APP/node_modules/preact');\nconst { act } = require('../../NEW APP/node_modules/preact/test-utils');\nconst { productionTs, productionFunctions } = require('./helpers/production-source.cjs');\nlet container;\nbeforeEach(()=>{container=document.createElement('div');document.body.appendChild(container);});\nafterEach(()=>{act(()=>render(null,container));container.remove();jest.restoreAllMocks();});\n\ndescribe('actual Preact hydration lifecycle',()=>{\n    function setup(loadPenDetail) {\n        const {useHydratedLivestockAnimals}=productionTs('NEW APP/src/lib/use-hydrated-livestock.ts',{\n            '@/lib/pen-detail':{loadPenDetail},\n            '@/lib/livestock-normalize':{normalizeLivestockAnimals:animals=>({animals,lodState:{}})},\n            '@/lib/livestock-hydrate':{\n                collectPensNeedingDetailHydration:rows=>[...new Set(rows.filter(r=>r.synthetic).map(r=>String(r.husbandryId)))],\n                mergeAnimalsWithPenHydration:(rows,by)=>rows.flatMap(r=>by[String(r.husbandryId)]||[r]),\n                penDetailAnimalsLookIndividual:()=>true,\n                penDetailAnimalsToLivestockRows:(_id,rows)=>rows,\n            },\n        });\n        function View(props){const state=useHydratedLivestockAnimals(props);return h('output',null,JSON.stringify(state.animals));}\n        return View;\n    }\n    const rows=()=>[{husbandryId:7,synthetic:true,health:0}];\n    test('a new payload refreshes detail for the same pen',async()=>{\n        let health=60;const load=jest.fn(async()=>({detail:{animals:[{husbandryId:7,health}]}}));const View=setup(load);\n        await act(async()=>{render(h(View,{animalsData:rows(),activeServerId:'A',activeFarmId:1}),container);});\n        expect(container.textContent).toContain('\"health\":60');health=90;\n        await act(async()=>{render(h(View,{animalsData:rows(),activeServerId:'A',activeFarmId:1}),container);});\n        expect(container.textContent).toContain('\"health\":90');expect(load).toHaveBeenCalledTimes(2);\n    });\n    test('same pen id in save B triggers B detail',async()=>{\n        const load=jest.fn(async(_id,opts)=>({detail:{animals:[{husbandryId:7,server:opts.serverId}]}}));const View=setup(load);\n        await act(async()=>{render(h(View,{animalsData:rows(),activeServerId:'A',activeFarmId:1}),container);});\n        await act(async()=>{render(h(View,{animalsData:rows(),activeServerId:'B',activeFarmId:1}),container);});\n        expect(load).toHaveBeenLastCalledWith('7',{serverId:'B'});expect(container.textContent).toContain('\"server\":\"B\"');\n    });\n    test('late A detail cannot replace B',async()=>{\n        let completeA;const load=jest.fn((_id,opts)=>opts.serverId==='A'?new Promise(resolve=>{completeA=resolve;}):Promise.resolve({detail:{animals:[{server:'B'}]}}));\n        const View=setup(load);\n        await act(async()=>{render(h(View,{animalsData:rows(),activeServerId:'A',activeFarmId:1}),container);});\n        await act(async()=>{render(h(View,{animalsData:rows(),activeServerId:'B',activeFarmId:1}),container);});\n        await act(async()=>{completeA({detail:{animals:[{server:'A'}]}});});\n        expect(container.textContent).toContain('\"server\":\"B\"');expect(container.textContent).not.toContain('\"server\":\"A\"');\n    });\n});\n\ntest('input rerender does not steal password focus, Escape uses latest callback',()=>{\n    const {useFocusTrap}=productionTs('NEW APP/src/lib/use-focus-trap.ts');\n    const descriptor=Object.getOwnPropertyDescriptor(HTMLElement.prototype,'offsetParent');\n    Object.defineProperty(HTMLElement.prototype,'offsetParent',{configurable:true,get(){return this.parentElement;}});\n    const first=jest.fn(),latest=jest.fn();\n    function Dialog({escape}){const ref=useFocusTrap(true,escape);return h('div',{ref},h('input',{name:'username'}),h('input',{name:'password',type:'password'}));}\n    try {\n        act(()=>render(h(Dialog,{escape:first}),container));\n        const password=container.querySelector('[name=password]');password.focus();\n        act(()=>render(h(Dialog,{escape:latest}),container));\n        expect(document.activeElement).toBe(password);\n        document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));\n        expect(latest).toHaveBeenCalledTimes(1);expect(first).not.toHaveBeenCalled();\n    } finally {\n        if(descriptor)Object.defineProperty(HTMLElement.prototype,'offsetParent',descriptor);\n        else delete HTMLElement.prototype.offsetParent;\n    }\n});\n\ntest('zero reported herd does not preserve nonzero clusters',()=>{\n    const {reconcileClustersToReported,clustersForFanOut}=productionFunctions('NEW APP/src/lib/livestock-fanout.ts',['reconcileClustersToReported','clustersForFanOut'],{\n        sumClusterCounts:clusters=>clusters.reduce((sum,c)=>sum+(Number(c.count)||0),0),\n    });\n    expect(reconcileClustersToReported([{count:5}],0)).toEqual([]);\n    expect(clustersForFanOut({numOfAnimalsReported:0},[{count:5}])).toEqual([]);\n    expect(clustersForFanOut({},[{count:5}])).toEqual([{count:5}]);\n});\ntest('measured zero health remains zero for synthetic rows',()=>{\n    const {displayAnimalHealth}=productionFunctions('NEW APP/src/lib/livestock-format.ts',['displayAnimalHealth']);\n    expect(displayAnimalHealth({health:0,__lodSynth:true})).toBe(0);\n});\ntest('Windows missing paths are not classified as rejected credentials',()=>{\n    const {classifyRawError}=productionFunctions('NEW APP/src/lib/ux-classify.ts',['classifyRawError'],{ERROR_CODES:{\n        E_PATH_DENIED:'path',E_AUTH_MISSING:'auth',E_PERMISSION_DENIED:'permission',E_LAN_TIMEOUT:'timeout',E_SETUP_LOCAL_ONLY:'local',E_INVALID_TOKEN:'token',E_SERVER_OFFLINE:'offline',E_LUA_STALE:'stale',E_SAVE_FAILED:'save',\n    }});\n    expect(classifyRawError('ENOENT C:\\\\Users\\\\Example\\\\savegame1')).toBe('path');\n    expect(classifyRawError('ENOTDIR C:\\\\Users\\\\Example')).toBe('path');\n    expect(classifyRawError('401 Unauthorized')).toBe('auth');\n});\n"},{"path":"FS25_FarmDashboard_App/fileCommit.cjs","content":"'use strict';\n\nconst fs = require('fs');\nconst path = require('path');\nconst crypto = require('crypto');\n\nfunction stagingPath(base) {\n    return String(base) + '.' + process.pid + '.' + crypto.randomBytes(6).toString('hex');\n}\n\n/** A failed rename never requires deleting the destination. Keep staged bytes on commit failure. */\nasync function downloadAndCommit(client, remotePath, localTmp, localFinal, options = {}) {\n    const attempts = Math.min(10, Math.max(1, parseInt(options.maxAttempts, 10) || 1));\n    const retryMs = Math.max(0, Number(options.retryDelayMs) || 0);\n    const current = () => typeof options.canCommit !== 'function' || options.canCommit();\n    const tmp = stagingPath(localTmp);\n    let lastError;\n    for (let attempt = 0; attempt < attempts; attempt++) {\n        if (!current()) return false;\n        let validated = false;\n        try {\n            await fs.promises.mkdir(path.dirname(tmp), { recursive: true });\n            await client.downloadTo(tmp, remotePath);\n            const stat = await fs.promises.stat(tmp);\n            if (!stat.isFile() || stat.size <= 0) throw new Error('empty download');\n            if (/\\.json$/i.test(localFinal)) {\n                JSON.parse((await fs.promises.readFile(tmp, 'utf8')).replace(/^\\uFEFF/, ''));\n            }\n            if (typeof options.validate === 'function') await options.validate(tmp);\n            validated = true;\n            if (!current()) {\n                await fs.promises.unlink(tmp).catch(() => {});\n                return false;\n            }\n            await fs.promises.rename(tmp, localFinal);\n            return true;\n        } catch (error) {\n            lastError = error;\n            if (!validated) await fs.promises.unlink(tmp).catch(() => {});\n        }\n        if (attempt + 1 < attempts && current() && retryMs > 0) {\n            await new Promise(resolve => setTimeout(resolve, retryMs * (attempt + 1)));\n        }\n    }\n    if (options.logFailures && lastError) {\n        console.warn('[fileCommit] ' + path.basename(localFinal) + ': ' + lastError.message);\n    }\n    return false;\n}\n\n/** Synchronous callers fail promptly; no main-thread spin and no delete-then-rename fallback. */\nfunction writeJsonAtomicSync(destination, value) {\n    const tmp = stagingPath(destination + '.tmp');\n    try {\n        const body = JSON.stringify(value, null, 2);\n        if (typeof body !== 'string') return false;\n        fs.mkdirSync(path.dirname(destination), { recursive: true });\n        fs.writeFileSync(tmp, body, { encoding: 'utf8', flag: 'wx' });\n        fs.renameSync(tmp, destination);\n        return true;\n    } catch (error) {\n        console.warn('[fileCommit] ' + path.basename(destination) + ': ' + error.message);\n        return false;\n    }\n}\n\nmodule.exports = { downloadAndCommit, writeJsonAtomicSync };\n"}]){if(fs.existsSync(entry.path))throw Error('New file already exists: '+entry.path);writes.push({file:entry.path,content:entry.content});}
for(const entry of writes){fs.mkdirSync(path.dirname(entry.file),{recursive:true});fs.writeFileSync(entry.file,entry.content,'utf8');console.log('UPDATED '+entry.file);}

